import { breadGroups } from "@/data/products";
import { visualForProduct } from "@/data/illustrative";

/**
 * Review-approved Breads product-card images.
 *
 * Asset bytes are reproducibly generated by scripts/build-reviewed-breads.py.
 * Only /breads renders these overrides; generic product illustrations and
 * category photos used elsewhere are deliberately left unchanged.
 *
 * The review accepted six edits of actual Bluepoint photos and 34 reframed
 * previously generated illustrations. An edited real photo must NOT be
 * conflated with a verified exact-SKU photograph (especially case quantities).
 */

type Source = {
  originalBluepointUrl: string;
  categorySource: string;
};

const sources: Record<string, Source> = {
  "french-breads": {
    originalBluepointUrl: "https://irp.cdn-website.com/59a1f314/dms3rep/multi/24--+Golden+Parisien+1.jpg",
    categorySource: "B03 — Golden Parisien",
  },
  "deli-loaves": {
    originalBluepointUrl: "https://irp.cdn-website.com/59a1f314/dms3rep/multi/Marble+Rye+%282%29.jpg",
    categorySource: "B04 — Marble rye",
  },
  "pan-loaves": {
    originalBluepointUrl: "https://irp.cdn-website.com/59a1f314/dms3rep/multi/Pan+Size+Variety+%283%29.jpg",
    categorySource: "B05 — Pan Size Variety",
  },
  "dinner-rolls": {
    originalBluepointUrl: "https://irp.cdn-website.com/59a1f314/dms3rep/multi/Brioche+Dinner+Rolls+4.jpg",
    categorySource: "B06 — Brioche Dinner Rolls",
  },
  "specialty-breads": {
    originalBluepointUrl: "https://irp.cdn-website.com/59a1f314/dms3rep/multi/16x4+Loaf+%283%29.jpg",
    categorySource: "B07 — 16x4 Vienna loaf",
  },
};

const sourceCropBySku: Record<string, string> = {
  "french-breads-golden-parisien-24-in": "B03-front",
  "deli-loaves-marble-rye": "B04-marble-slice",
  "pan-loaves-vienna-white": "B05-white-slice",
  "dinner-rolls-brioche-dozen": "B06-front",
  "dinner-rolls-brioche-case-120": "B06-front",
  "specialty-breads-16x4-vienna": "B07-front",
};

// Verified visual product-family matches do not imply size or wrapping verification.
const verifiedProductFamily = new Set([
  "french-breads-golden-parisien-24-in",
  "deli-loaves-marble-rye",
  "specialty-breads-16x4-vienna",
]);

const coveredGroups = new Set(Object.keys(sources));
const coveredIds = new Map(
  breadGroups
    .filter((group) => coveredGroups.has(group.id))
    .flatMap((group) => group.items.map((product) => [product.id, group.id] as const)),
);

export const reviewedBreadProductIds = Object.freeze([...coveredIds.keys()]);

export type ReviewedBreadPhoto = {
  webp: string;
  avif?: string;
  alt: string;
  width: 960;
  height: 720;
  illustrative: boolean;
  label: "Photo edited" | "Illustrative image";
  provenance: {
    originalBluepointUrl: string;
    categorySource: string;
    sourceObject: string;
    imageKind: "original-photo-edited" | "legacy-illustration-reframed";
    exactSkuVerified: boolean;
  };
};

export function reviewedBreadPhotoFor(productId: string): ReviewedBreadPhoto | undefined {
  const groupId = coveredIds.get(productId);
  if (!groupId) return undefined;
  const reference = sources[groupId];
  const cropObject = sourceCropBySku[productId];
  const actualPhoto = cropObject !== undefined;
  const previousIllustration = visualForProduct(productId);
  return {
    webp: "/images/catalog/reviewed-breads/" + productId + ".webp",
    width: 960,
    height: 720,
    illustrative: !actualPhoto,
    label: actualPhoto ? "Photo edited" : "Illustrative image",
    alt: actualPhoto
      ? "Edited original Bluepoint Bakery photograph representing " + productId.replaceAll("-", " ") + "."
      : "Illustrative bakery photograph representing " + productId.replaceAll("-", " ") + "; not a verified Bluepoint SKU photograph.",
    provenance: {
      originalBluepointUrl: reference.originalBluepointUrl,
      categorySource: reference.categorySource,
      sourceObject: actualPhoto ? cropObject : previousIllustration?.webp ?? "unknown original illustration",
      imageKind: actualPhoto ? "original-photo-edited" : "legacy-illustration-reframed",
      exactSkuVerified: verifiedProductFamily.has(productId),
    },
  };
}
